"""Server-rendered console interface. Dynamic values are escaped; no scripts or trackers."""
from datetime import datetime, timezone
from html import escape
from starlette.responses import HTMLResponse

GAME = 'Castlevania: Belmont’s Curse'

def esc(value):
    return escape(str(value), quote=True)

def hidden(name, value):
    return f'<input type="hidden" name="{esc(name)}" value="{esc(value)}">'

def page(title, body):
    return HTMLResponse(f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><title>{esc(title)} · Game Assist</title><link rel="stylesheet" href="/assets/console.css"></head><body><a class="skip" href="#main">К содержимому</a><div class="shell"><header class="topbar"><a class="brand" href="/" aria-label="Game Assist — главная"><span class="brand-mark" aria-hidden="true">g<span>+</span></span><span>GAME ASSIST<small>ТВОЙ ИГРОВОЙ СПУТНИК</small></span></a><span class="privacy-pill"><i aria-hidden="true"></i>Без спойлеров</span></header><main id="main">{body}</main><footer><span>Твоя игра. Твой темп.</span><span>Только чтение · Никаких изменений сохранений</span></footer><nav class="dock" aria-label="Основная навигация"><a href="/">◈ <span>Главная</span></a><a href="/#assistant">✦ <span>Помощник</span></a><a href="/setup">⊞ <span>Устройство</span></a></nav></div></body></html>''')

def game_tile(status='Сводки пока нет'):
    return f'''<article class="game-tile"><div class="game-art" aria-hidden="true"><span class="orbit orbit-one"></span><span class="orbit orbit-two"></span><span class="crosshair">+</span><span class="art-label">SAVE / SIGNAL</span><span class="art-number">01</span></div><div class="game-meta"><span class="eyebrow">ПОДДЕРЖИВАЕМАЯ ИГРА</span><h2>{GAME}</h2><span class="tag">{esc(status)}</span></div></article>'''

def landing_body():
    return f'''<section class="hero"><div><span class="eyebrow">ПРОДОЛЖИМ С ТОГО ЖЕ МЕСТА</span><h1>В игре — ты.<br>Рядом — <em>помощник.</em></h1><p class="lead">Твой игровой контекст под рукой. Только известные факты, никаких подсказок из будущего.</p><a class="button primary" href="/login">Войти через Steam <span aria-hidden="true">↗</span></a><p class="micro">Пароль вводится только на сайте Steam.</p></div>{game_tile('Ожидает твоего контекста')}</section><section class="section-head" id="assistant"><div><span class="eyebrow">БЕЗ ЛИШНЕЙ НАСТРОЙКИ</span><h2>Помощник, а не панель управления</h2></div><span class="section-index">01 — 03</span></section><div class="feature-grid"><article class="panel"><span class="step">01</span><h3>Связать аккаунт</h3><p>Вход через Steam подтверждает аккаунт. Он не открывает доступ к облачным сохранениям.</p></article><article class="panel"><span class="step">02</span><h3>Играть в своём темпе</h3><p>Можно начать без установки: рассказать помощнику, где ты сейчас и какая помощь нужна.</p></article><article class="panel"><span class="step">03</span><h3>Добавить контекст</h3><p>Необязательный компаньон на Deck передаёт только разрешённую сводку. Доступ всегда можно отозвать.</p><a class="text-link" href="/setup">Как подключить Deck →</a></article></div><aside class="notice"><span class="signal" aria-hidden="true">!</span><div><strong>Честно о возможностях</strong><p>Автоматическое чтение Steam Cloud недоступно. Прохождение, карта и достижения не определяются по этим данным.</p></div></aside>'''

def timestamp(value):
    try:
        return datetime.fromtimestamp(float(value), timezone.utc).strftime('%d.%m.%Y · %H:%M UTC')
    except (ValueError, TypeError, OverflowError, OSError):
        return 'Время неизвестно'

def scalar_text(scalar):
    if isinstance(scalar, dict) and scalar.get('status') == 'known' and type(scalar.get('value')) in (int, float):
        return str(scalar['value'])
    return 'Неизвестно'

def home_body(projection, csrf, inbox=None, capabilities=None):
    capabilities = capabilities or {}
    mcp_url = capabilities.get('mcp_url')
    connection = (f'<details class="connect-details"><summary>Подключить к своему помощнику</summary><label for="mcp-url">Адрес сервера MCP · только чтение</label><input id="mcp-url" class="endpoint" readonly value="{esc(mcp_url)}"><ol><li>В веб-версии Claude открой Settings → Connectors → Add custom connector.</li><li>Укажи имя Game Assist и адрес сервера выше.</li><li>Пройди вход через Steam и проверь разрешение на чтение сводок.</li></ol><p class="micro">Доступность настройки зависит от аккаунта и правил рабочей области. Работа пользовательского MCP в мобильном ChatGPT здесь не проверена.</p><a class="text-link" href="https://support.claude.com/en/articles/11175166-get-started-with-custom-connectors-using-remote-mcp" rel="noreferrer">Инструкция Claude ↗</a></details>' if mcp_url else '')
    games = projection.get('games', [])
    game = next((g for g in games if g.get('appid') == 4231820), None)
    summary = game.get('summary') if game else None
    status = 'Сводка от устройства' if summary else 'Сводки пока нет'
    if summary:
        scalars = summary.get('player_scalars', {})
        metrics = ''.join(f'<div class="metric"><dt>{label}</dt><dd>{esc(scalar_text(scalars.get(key)))}</dd></div>' for key, label in [('currentHealth','Текущее здоровье'),('currentMana','Текущая мана'),('healthUpgradeFragmentCount','Фрагменты здоровья'),('manaUpgradeFragmentCount','Фрагменты маны')])
        progress = f'<div class="section-head"><h2>Последний сигнал</h2><span class="tag">От устройства</span></div><dl class="metrics">{metrics}</dl><p class="micro">Получено: {esc(timestamp(game.get("received_at")))}</p><p class="muted">Это переданные значения, не независимая проверка игры. Время самого сохранения неизвестно. Здоровье и мана — не максимумы; смысл счётчиков фрагментов не подтверждён.</p>'
    else:
        progress = '<span class="eyebrow">ИГРОВОЙ КОНТЕКСТ</span><h2>Пока без сводки</h2><p>Не будем угадывать твой прогресс. Steam Cloud недоступен; вход в Steam сам по себе не загружает сохранения.</p><a class="button secondary" href="/setup">Добавить Deck <span>↗</span></a><p class="micro">Необязательно. Можно пользоваться помощником без устройства.</p>'
    inbox = inbox or {'enabled':False, 'items':[]}
    enabled = bool(inbox.get('enabled'))
    updates = ''.join(f'<li><div><p>{esc(item.get("message", "Новая сводка устройства"))}</p><span class="micro">{esc(timestamp(item.get("created_at")))}</span></div>' + (f'<form method="post" action="/account/notifications/read">{hidden("csrf", csrf)}{hidden("notification_id", item.get("id", ""))}<button class="small secondary">Прочитано</button></form>' if not item.get('read') else '<span class="tag">Прочитано</span>') + '</li>' for item in inbox.get('items', []))
    can_enable = bool(inbox.get('can_enable', False))
    notification_control = (f'<form class="inline-form" method="post" action="/account/notifications">{hidden("csrf", csrf)}{hidden("appid","4231820")}{hidden("enabled","no" if enabled else "yes")}<button class="secondary">{"Выключить обновления" if enabled else "Включить обновления"}</button><p class="micro">Только на этой странице, не push. Без компаньона новых сигналов не будет.</p></form>' if enabled or can_enable else '<p class="micro">Для обновлений нужен компаньон и разрешение на чтение сводки. Это необязательно; уведомления появляются только здесь, не push.</p>')
    updates = f'<ul class="inbox-list">{updates}</ul>' if updates else '<div class="empty-state"><span aria-hidden="true">⌁</span><h3>Здесь появятся изменения</h3><p>Пока нет уведомлений. Только реальные обновления разрешённой сводки — без догадок о прохождении.</p></div>'
    return f'''<section class="welcome"><div><span class="eyebrow">ТВОЯ ИГРОВАЯ СТАНЦИЯ</span><h1>Продолжим <em>играть.</em></h1><p class="lead">Контекст рядом. Всё остальное — за тобой.</p></div><span class="tag connected">Steam подключён</span></section><div class="play-grid">{game_tile(status)}<section class="panel progress-panel">{progress}</section></div><section class="assistant-panel" id="assistant"><div class="assistant-symbol" aria-hidden="true">✦</div><div><span class="eyebrow">ПОМОЩНИК БЕЗ СПОЙЛЕРОВ</span><h2>Куда ты хочешь двигаться?</h2><p>Расскажи своему помощнику, где находишься и что уже открыл. Если данных мало, он должен уточнить, а не придумывать.</p><p class="micro">На этом сайте нет чата. ChatGPT или Claude подключаются отдельно через OAuth, с твоего разрешения.</p>{connection}</div></section><section id="updates" class="panel"><div class="section-head"><div><span class="eyebrow">СИГНАЛЫ ОТ УСТРОЙСТВА</span><h2>Твои обновления</h2></div><span class="tag">{'Включены' if enabled else 'Выключены'}</span></div><p class="micro">Steam Cloud недоступен. Уведомления только на сайте, не push.</p>{updates}{notification_control}</section><details class="panel account"><summary>Подключения и доступ</summary><p>Компаньон необязателен. Свяжи только своё устройство и отдельно разреши помощнику читать сводку.</p><div class="actions"><a class="button secondary" href="/devices/approve">Подключить по коду</a><a class="button secondary" href="/setup">Настройка Deck</a></div><div class="account-actions"><form method="post" action="/logout">{hidden('csrf',csrf)}<button class="secondary">Выйти</button></form><form method="post" action="/account/revoke">{hidden('csrf',csrf)}<button class="danger">Отозвать весь доступ</button><span class="micro">Отключит устройства и помощников, удалит сводки.</span></form></div></details>'''

def device_body(csrf):
    return f'''<div class="narrow"><a class="text-link" href="/">← На главную</a><span class="eyebrow">ПОДКЛЮЧЕНИЕ УСТРОЙСТВА</span><h1>Один код.<br><em>Твой Deck.</em></h1><p class="lead">Введи только код, показанный на твоём Steam Deck. Не подтверждай код, присланный другим человеком.</p><form class="panel form-stack" method="post">{hidden('csrf',csrf)}<label for="device-code">Код устройства</label><input id="device-code" class="code-input" name="user_code" minlength="8" maxlength="8" pattern="[A-Fa-f0-9]{{8}}" autocomplete="off" autocapitalize="characters" spellcheck="false" placeholder="A1B2C3D4" required><label for="game-select">Игра</label><select id="game-select" name="appid" required><option value="">Выбери игру</option><option value="4231820">{GAME}</option></select><fieldset><legend>Что разрешено передавать</legend><label class="check"><input type="checkbox" name="saves.summary" value="yes"><span>Четыре значения игрока<small>Текущие здоровье, мана и два сырых счётчика фрагментов. Не максимумы.</small></span></label><label class="check"><input type="checkbox" name="saves.metadata" value="yes"><span>Метаданные сохранения<small>Удалённый приём метаданных пока не реализован.</small></span></label></fieldset><p class="micro">Выбери хотя бы одно разрешение. Доступ ChatGPT / Claude подтверждается отдельно.</p><button class="primary">Подключить это устройство →</button><a class="text-link" href="/">Отмена</a></form></div>'''

def consent_body(csrf, req, client_label):
    return f'''<div class="narrow"><span class="eyebrow">ТЫ УПРАВЛЯЕШЬ ДОСТУПОМ</span><h1>Подключить<br><em>помощника?</em></h1><section class="panel"><p>Этот клиент сможет читать только разрешённые тобой игровые сводки. Переданные факты покинут Game Assist.</p><div class="client-label"><span class="eyebrow">КЛИЕНТ И АДРЕС ВОЗВРАТА</span><p>{esc(client_label)}</p></div><p>Без сырых сохранений и Steam ID. Только чтение; доступ можно отозвать на главной.</p><form class="form-stack" method="post">{hidden('csrf',csrf)}{hidden('request',req)}<button class="primary">Разрешить чтение сводки →</button><a class="text-link" href="/">Не подключать</a></form></section></div>'''

def approved_body():
    return '<div class="narrow"><span class="eyebrow">ГОТОВО</span><h1>Deck <em>подключён.</em></h1><section class="panel"><p>Вернись на Steam Deck, чтобы завершить настройку. Доступ можно в любой момент отозвать на главной.</p><a class="button primary" href="/">На главную →</a></section></div>'

def setup_body(issuer, checksum, command=None):
    intro = '<div class="narrow setup"><a class="text-link" href="/">← На главную</a><span class="eyebrow">НЕОБЯЗАТЕЛЬНЫЙ КОМПАНЬОН</span><h1>Твой Deck.<br><em>Чуть ближе.</em></h1><p class="lead">Для автоматической передачи разрешённой сводки. Можно продолжить без установки — Steam Cloud здесь недоступен.</p>'
    if not checksum:
        return intro + '<section class="panel"><h2>Загрузка пока недоступна</h2><p>Архив компаньона ещё не собран. Сейчас установить его с этого сервиса нельзя.</p><a class="button secondary" href="/">Вернуться к игре</a></section></div>'
    return intro + f'''<ol class="setup-steps"><li class="panel"><span class="step">01</span><h2>Открой эту страницу на Deck</h2><p>Переключись в Desktop Mode и открой <code>{esc(issuer+'/setup')}</code>. Вход в ChatGPT на Deck не нужен.</p><p class="micro">Нужны Python 3.10+, модуль venv и активная сессия systemctl --user. Если их нет — остановись: не используй sudo и не отключай защиту SteamOS.</p></li><li class="panel"><span class="step">02</span><h2>Скачай и проверь исходники</h2><p>Сохрани архив как deck-companion.zip в Downloads. Только исходный код стандартной библиотеки: без pip-пакетов и готовых бинарных файлов.</p><div class="actions"><a class="button primary" href="/downloads/deck-companion.zip">Скачать ZIP ↓</a><a class="button secondary" href="/downloads/deck-companion.zip.sha256">SHA256</a></div><details><summary>Проверка и команды установки</summary><p>Изучи исходники и команды. Ничего не запускается автоматически. В Konsole сначала проверь контрольную сумму; продолжай только после OK.</p><pre>{esc(command or '')}</pre><p class="micro">SHA256: <code>{esc(checksum)}</code></p></details></li><li class="panel"><span class="step">03</span><h2>Разреши только нужное</h2><p>Явно выбери путь к сохранению. На телефоне войди через Steam по адресу сопряжения, сравни код с кодом на своём Deck, выбери игру AppID 4231820 и разрешённую сводку из четырёх полей.</p><p>Установка спросит разрешение перед включением фоновой службы. Сохранения не изменяются. Сопряжение действует 30 дней.</p><a class="button secondary" href="/devices/approve">Ввести код устройства →</a></li></ol><aside class="notice"><span class="signal">!</span><div><strong>Что важно знать</strong><p>Фоновая работа в Gaming Mode ещё требует проверки на реальном Deck. Бесплатный хостинг может просыпаться около минуты. Помощник на телефоне подключается отдельно через OAuth.</p></div></aside></div>'''
